// Why Code: citările agentului se verifică pe fragmentele întoarse efectiv de unealta de căutare (pași intermediari),
// plus răspunsul spre aplicație (același contract ca înainte) și rândul din ai_calls.
const NOT_FOUND = 'Nu găsesc în documentele disponibile.';
const prep = $('Prepare query').first().json;
const res = $input.first().json;
const out = typeof res.output === 'string' ? (() => { try { return JSON.parse(res.output); } catch { return null; } })() : res.output;

// fragmentele găsite: observațiile uneltei de căutare (text JSON: listă de {type:'text', text:'{"pageContent","metadata"}'})
const docs = [];
const take = (d) => { if (d && typeof d === 'object' && typeof d.pageContent === 'string') docs.push({ content: d.pageContent, meta: d.metadata ?? {} }); };
const walk = (v) => {
  if (typeof v === 'string') { try { walk(JSON.parse(v)); } catch { /* text simplu */ } return; }
  if (Array.isArray(v)) { v.forEach(walk); return; }
  if (v && typeof v === 'object') { if (typeof v.pageContent === 'string') take(v); else if (typeof v.text === 'string') walk(v.text); }
};
const steps = Array.isArray(res.intermediateSteps) ? res.intermediateSteps : [];
for (const s of steps) walk(s?.observation);

const key = (t, p) => String(t ?? '').trim().toLowerCase() + '|' + (p == null || p === '' ? '' : Number(p));
const found = new Map();
for (const d of docs) { const k = key(d.meta.title, d.meta.page); if (!found.has(k)) found.set(k, d); }
const answer = typeof out?.answer === 'string' ? out.answer.trim() : '';
const cited = Array.isArray(out?.sources) ? out.sources : [];
const used = [];
for (const c of cited) {
  const d = found.get(key(c?.title, c?.page)) ?? (c?.page == null ? [...found.values()].find((x) => key(x.meta.title, null) === key(c?.title, null)) : undefined);
  if (d && !used.includes(d)) used.push(d);
}
const ok = answer.length > 0 && used.length > 0 && !answer.startsWith('Nu găsesc în documentele');
const page = (d) => (Number.isInteger(Number(d.meta.page)) && Number(d.meta.page) > 0 ? Number(d.meta.page) : null);
const sources = ok ? used.map((d, i) => ({ n: i + 1, title: d.meta.title, insurer: d.meta.insurer || null, docType: d.meta.doc_type || null, collection: d.meta.collection || null, page: page(d), heading: null, url: d.meta.source_url || null, snippet: d.content.slice(0, 500) })) : [];
const cites = sources.map((s) => '[' + s.title + (s.page ? ', pag. ' + s.page : '') + ']').join(' ');
const response = ok ? { found: true, answer: answer + ' ' + cites, sources } : { found: false, answer: NOT_FOUND, sources: [] };

// Tokeni: nodul Agent nu-i întoarce, iar sub-nodul modelului nu e accesibil din Code, deci estimare din text, calibrată pe
// exec. 482 (15 nov): 2 apeluri, real 3.446 la intrare / 389 la ieșire (gpt-oss numără și raționamentul la ieșire).
const calls = Math.max(1, steps.length + 1);
const obsChars = steps.reduce((a, s) => a + String(s?.observation ?? '').length, 0);
const inTok = Math.round((calls * (prep.systemMessage.length + prep.chatInput.length + 600) + obsChars) / 2.6);
const outTok = Math.round(JSON.stringify(out ?? '').length / 2.6) + 130 * calls;
const PRICES = { 'openai/gpt-oss-120b': [0.15, 0.6], 'openai/gpt-oss-20b': [0.075, 0.3] }; // ca apps/web/lib/ai/pricing.ts
const model = $env.MODEL_KB || 'openai/gpt-oss-120b';
const price = PRICES[model];
const aiCalls = [{
  workflow: 'WF04', task: 'rag_agent@2', provider: 'groq', model, redacted: !!prep.redacted,
  input_tokens: inTok, output_tokens: outTok, cost_usd: price ? (inTok * price[0] + outTok * price[1]) / 1e6 : null,
  latency_ms: Date.now() - prep.startedAt, success: out !== null, error: out === null ? 'răspuns LLM invalid' : null,
}];
return [{ json: { response, aiCalls, debug: { steps: steps.length, docs: docs.length, cited: cited.length, used: used.length } } }];
